// Запросы в Travelpayouts под первое плечо: Питер -> Актау, сентябрь 2026.
// Кроме сквозного маршрута тянем соседей, и вот зачем:
//   legA/legB — половинки московской схемы, из них в Aggregate собирается self-transfer;
//   deep      — города «за» Актау, нужны для подсказок hidden-city.
const MONTH = '2026-09';

const Q = [
  { origin: 'LED', destination: 'SCO', leg: 'through' },
  { origin: 'LED', destination: 'MOW', leg: 'legA' },   // MOW — метро-код: SVO+DME+VKO+ZIA
  { origin: 'MOW', destination: 'SCO', leg: 'legB' },
  { origin: 'LED', destination: 'ALA', leg: 'deep' },
  { origin: 'LED', destination: 'NQZ', leg: 'deep' },
  { origin: 'LED', destination: 'TAS', leg: 'deep' },
  { origin: 'LED', destination: 'GUW', leg: 'deep' },
];

return Q.map(q => ({ json: { ...q, month: MONTH } }));

// Исторические цены Travelpayouts — нужны, чтобы ответить на вопрос
// «а 28 000 ₽ это вообще дёшево?». Своей таблицы не заводим, берём чужой архив.
// Эндпоинт один — /v2/prices/latest: реально найденные цены за период
// (show_to_affiliates=false), по ним считаем медиану и исторический минимум.
// /v1/prices/calendar пробовали 2026-08-17 и ВЫКИНУЛИ: он отдаёт цены ТУДА-ОБРАТНО
// (все записи с return_at, 45–64 тыс. против one-way 12–22 тыс.) и игнорирует
// запрошенный месяц, растягиваясь на год вперёд. В медиане это давало +60 % к «обычной цене».
// URL и query собираются здесь, HTTP-нода их только исполняет.
const YEAR_START = '2026-01-01';
const ROUTES = [['LED', 'SCO'], ['LED', 'MOW'], ['MOW', 'SCO']];

const out = [];
for (const [origin, destination] of ROUTES) {
  out.push({ json: {
    key: `${origin}-${destination}`, kind: 'latest',
    url: 'https://api.travelpayouts.com/v2/prices/latest',
    qs: {
      origin, destination, currency: 'rub',
      period_type: 'year', beginning_of_period: YEAR_START,
      group_by: 'dates', one_way: 'true', sorting: 'price',
      page: '1', limit: '1000', show_to_affiliates: 'false',
    },
  } });
}
return out;

// ===== Плечо 1: Питер -> Актау (SCO), 15-25 сентября 2026 =====
// На старте живой источник один — Travelpayouts (кэш Aviasales, данные до 48 ч).
// Ноды перевозчиков (SCAT, Air Astana, FlyArystan, Уральские) добавляются позже,
// поэтому разбор идёт через общий плоский список offers[]: новому источнику
// достаточно положить туда свои записи в том же формате и он поедет дальше сам.
//
// offer = { from, to, date, depart_at, price, airline, transfers, src, kind }
//   kind: 'direct' | 'connect' | 'self' | 'hidden'
//   'self' (две отдельные брони) и 'hidden' считаются отдельно и в основной
//   порог алерта НЕ попадают — у них своя цена риска.
const SUF = ''; // '' для крона, ' Cmd' для ветки команды

const WINDOW = { min: '2026-09-15', max: '2026-09-25' };
const HOME = 'LED';
const TARGET = 'SCO';
const HUB = 'MOW';                        // self-transfer через Москву
const DEEP = ['ALA', 'NQZ', 'TAS', 'GUW']; // города «за» Актау — под hidden-city
const ASSUMED_LEG_H = 3;                   // если перевозчик не отдал длительность
const MIN_LAYOVER_H = 4;                   // меньше — на самостоятельную стыковку не идём
const MAX_LAYOVER_H = 36;

const AIRLINES = {
  DP: 'Победа', '5N': 'Смартавиа', U6: 'Уральские', FV: 'Россия', SU: 'Аэрофлот',
  S7: 'S7', N4: 'Nordwind', WZ: 'Red Wings', A4: 'Азимут', YC: 'Ямал', UT: 'ЮТэйр',
  DV: 'SCAT', KC: 'Air Astana', IQ: 'Qazaq Air', HY: 'Uzbekistan', TK: 'Turkish',
  FZ: 'flydubai', J2: 'AZAL', VJ: 'VietJet', EK: 'Emirates', ZF: 'Азур', EO: 'Икар',
  // добавлены по факту выдачи 17.08.2026; C6 не расшифрован — покажется кодом как есть
  PC: 'Pegasus', B2: 'Belavia', '6R': 'Алроса',
};
const CITY = {
  LED: 'Санкт-Петербург', MOW: 'Москва', SCO: 'Актау', ALA: 'Алматы',
  NQZ: 'Астана', TAS: 'Ташкент', GUW: 'Атырау',
};

const inWindow = d => Boolean(d && d >= WINDOW.min && d <= WINDOW.max);
const hours = ms => ms / 3600000;

// --- 1. Travelpayouts v3: единственный источник на старте -------------------
const offers = [];
try {
  for (const item of $('Travelpayouts' + SUF).all()) {
    const r = item.json || {};
    if (r.success === false) continue;
    const rows = Array.isArray(r.data) ? r.data : (Array.isArray(r) ? r : []);

    for (const t of rows) {
      const depart_at = String(t.departure_at || t.depart_date || '');
      const date = depart_at.slice(0, 10);
      if (!inWindow(date)) continue;

      const price = Number(t.price != null ? t.price : t.value);
      if (!Number.isFinite(price) || price <= 0) continue;

      const transfers = Number(t.transfers != null ? t.transfers : t.number_of_changes);
      const dur = Number(t.duration_to || t.duration);

      offers.push({
        from: t.origin, to: t.destination, date, depart_at,
        price,
        airline: AIRLINES[t.airline] || t.airline || 'н/д',
        transfers: Number.isFinite(transfers) ? transfers : null,
        duration_min: Number.isFinite(dur) && dur > 0 ? dur : null,
        src: 'tp',
        kind: transfers === 0 ? 'direct' : 'connect',
        link: t.link || null,
      });
    }
  }
} catch (e) {}

// --- 1b. tutu: минимум по всем перевозчикам, включая тех, кого нет в кэше TP ---
// Ответ — плоский объект по датам, направление в нём НЕ указано, поэтому
// сопоставляем с запросами по индексу. Упавший запрос (continueRegularOutput)
// приходит item'ом с json.error — такую пару просто пропускаем.
const ruToIso = s => {
  const m = String(s || '').match(/^(\d{2})\.(\d{2})\.(\d{4})$/);
  return m ? `${m[3]}-${m[2]}-${m[1]}` : null;
};
try {
  const asked = $('Tutu Queries' + SUF).all();
  const answers = $('Tutu' + SUF).all();
  if (answers.length === asked.length) {
    asked.forEach((q, i) => {
      const data = (answers[i] || {}).json || {};
      if (data.error || Array.isArray(data)) return;
      for (const [dru, v] of Object.entries(data)) {
        const date = ruToIso(dru);
        if (!inWindow(date)) continue;
        const price = Number(v && v.price);
        if (!Number.isFinite(price) || price <= 0) continue;
        offers.push({
          from: q.json.from, to: q.json.to, date,
          // времени вылета tutu не даёт — для стыковки берём условный полдень,
          // поэтому self-transfer на tutu-ценах помечен как приблизительный
          depart_at: `${date}T12:00:00+03:00`,
          price, airline: 'мин. цена tutu', transfers: null, duration_min: null,
          src: 'tutu', kind: 'connect', link: null,
        });
      }
    });
  }
} catch (e) {}

// --- 2. Self-transfer через Москву -----------------------------------------
// Две отдельные брони: дешёвый лоукостер до Москвы + отдельный билет до Актау.
// Стыковку проверяем по времени вылета/прилёта, а не «по датам» — иначе бот
// предложит схему, где второй рейс улетает раньше, чем прилетает первый.
const legMin = (from, to) => {
  const byDate = {};
  for (const o of offers) {
    if (o.from !== from || o.to !== to) continue;
    if (!byDate[o.date] || o.price < byDate[o.date].price) byDate[o.date] = o;
  }
  return Object.values(byDate);
};

const arrivalOf = o => {
  const dep = new Date(o.depart_at);
  if (isNaN(dep)) return null;
  const mins = o.duration_min != null ? o.duration_min : ASSUMED_LEG_H * 60;
  return new Date(dep.getTime() + mins * 60000);
};

const selfCombos = [];
const legA = legMin(HOME, HUB);
const legB = legMin(HUB, TARGET);
for (const a of legA) {
  const arr = arrivalOf(a);
  for (const b of legB) {
    const dep = new Date(b.depart_at);
    if (!arr || isNaN(dep)) continue;
    const gap = hours(dep - arr);
    if (gap < MIN_LAYOVER_H || gap > MAX_LAYOVER_H) continue;
    selfCombos.push({
      price: a.price + b.price,
      date: a.date, arrive_date: b.date,
      layover_h: Math.round(gap * 10) / 10,
      legA: a, legB: b,
      kind: 'self', src: 'tp',
      from: HOME, to: TARGET,
      airline: `${a.airline} + ${b.airline}`,
    });
  }
}
selfCombos.sort((x, y) => x.price - y.price);

// --- 3. Hidden-city: пока только подсказка ---------------------------------
// Настоящий hidden-city требует сегментов маршрута, а Travelpayouts их не отдаёт.
// Поэтому честно сравниваем: если долететь «дальше» дешевле, чем до Актау —
// сообщаем цифру и просим проверить глазами, есть ли там стыковка в SCO.
const cheapest = list => list.slice().sort((a, b) => a.price - b.price)[0] || null;
const through = offers.filter(o => o.from === HOME && o.to === TARGET);
const bestThrough = cheapest(through);

const hidden = [];
for (const dst of DEEP) {
  const best = cheapest(offers.filter(o => o.from === HOME && o.to === dst));
  if (!best) continue;
  if (bestThrough && best.price >= bestThrough.price) continue; // не дешевле — не подсказка
  hidden.push({
    ...best, kind: 'hidden',
    saving: bestThrough ? bestThrough.price - best.price : null,
    city: CITY[dst] || dst,
  });
}
hidden.sort((a, b) => a.price - b.price);

// --- 4. Архив цен: медиана и исторический минимум ---------------------------
// Ответ на «дёшево или нет». Схемы этих эндпоинтов живьём не проверены,
// поэтому читаем максимально терпимо и молча пропускаем всё, что не разобралось.
// Копим два пула: цены на даты НАШЕГО окна (точнее) и вообще все (шире выборка).
// Если по окну набралось мало точек — падаем на общий пул, иначе медиана скачет.
const history = {}, historyWin = {};
const pushHist = (key, price, date) => {
  if (!Number.isFinite(price) || price <= 0) return;
  (history[key] = history[key] || []).push(price);
  if (inWindow(date)) (historyWin[key] = historyWin[key] || []).push(price);
};
try {
  for (const item of $('TP History' + SUF).all()) {
    const r = item.json || {};
    if (r.success === false) continue;
    const data = r.data;

    if (!Array.isArray(data)) continue;               // ждём массив от /v2/prices/latest
    for (const t of data) {
      if (!t || !t.origin || !t.destination) continue;
      if (t.return_date) continue;                     // цены туда-обратно нам не с чем сравнивать
      pushHist(`${t.origin}-${t.destination}`,
               Number(t.value != null ? t.value : t.price),
               String(t.depart_date || '').slice(0, 10));
    }
  }
} catch (e) {}

const MIN_SAMPLE = 10;
const stats = {};
for (const key of Object.keys(history)) {
  const win = historyWin[key] || [];
  const useWin = win.length >= MIN_SAMPLE;
  const s = (useWin ? win : history[key]).slice().sort((a, b) => a - b);
  stats[key] = {
    min: s[0],
    median: s[Math.floor(s.length / 2)],
    count: s.length,
    scope: useWin ? 'наши даты' : 'все даты',
  };
}

// --- 5. Сводка --------------------------------------------------------------
const byDate = {};
for (const o of through) {
  if (!byDate[o.date] || o.price < byDate[o.date].price) byDate[o.date] = o;
}

return [{ json: {
  window: WINDOW,
  route: { from: HOME, to: TARGET, label: `${CITY[HOME]} → ${CITY[TARGET]}` },
  through: {
    best: bestThrough,
    byDate: Object.values(byDate).sort((a, b) => (a.date < b.date ? -1 : 1)),
    count: through.length,
  },
  self: { best: selfCombos[0] || null, top: selfCombos.slice(0, 3), count: selfCombos.length },
  hidden: { top: hidden.slice(0, 3), count: hidden.length },
  stats,
  count: offers.length,
  bySource: offers.reduce((acc, o) => { acc[o.src] = (acc[o.src] || 0) + 1; return acc; }, {}),
} }];

// ===================== НАСТРОЙКИ =====================
const THRESHOLD = 17000;       // 🔥 жёсткий порог по сквозному LED→SCO, ₽
const SELF_THRESHOLD = 17000;  // 🔥 порог для суммы двух отдельных броней
const DROP_PCT = 12;           // 📉 мягкий алерт: падение от прошлого минимума, %
const CHAT_ID = '648226895';
// Окно сузилось до 15–25.09, пороги пересчитаны по живому прогону 17.08.2026:
//   сквозной LED→SCO в окне — 17 375 ₽ (Pegasus, 15.09), медиана по датам 23 337 ₽;
//   через Москву — 22 631 ₽, то есть ХУЖЕ сквозного.
// (Для справки: вне окна, 26–27.09, было 12 703–13 352 ₽ — самые дешёвые даты сентября.)
// Пороги стоят у текущего минимума: алерт = реальное падение, а не «оно и так столько».
// Две брони имеют смысл только когда бьют сквозной билет — отсюда одинаковый порог.
// =====================================================

const agg = $('Aggregate').first().json;
const store = $getWorkflowStaticData('global'); // переживает запуски, без внешней БД

const MONTHS = ['янв', 'фев', 'мар', 'апр', 'мая', 'июн',
                'июл', 'авг', 'сен', 'окт', 'ноя', 'дек'];
const dm = iso => {
  const p = String(iso).split('-');
  return p.length === 3 ? `${Number(p[2])} ${MONTHS[Number(p[1]) - 1]}` : iso;
};
const rub = n => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + ' ₽';
const stops = o => o.transfers === 0 ? 'прямой'
  : o.transfers > 0 ? `${o.transfers} пересадк${o.transfers === 1 ? 'а' : 'и'}`
  : 'пересадки не указаны';
const describe = o => `${rub(o.price)} · ${dm(o.date)} · ${o.airline} · ${stops(o)}`;

// «дёшево или нет» — по чужому архиву Travelpayouts
const verdict = (key, price) => {
  const s = (agg.stats || {})[key];
  if (!s || !s.median || !s.count) return '';
  const pct = Math.round((price / s.median) * 100);
  // ВАЖНО про смысл цифры: /v2/prices/latest с group_by=dates отдаёт по одной
  // самой дешёвой цене НА КАЖДУЮ ДАТУ. Значит медиана — это «типичная дата», а не
  // «исторический уровень цен». Сравнение идёт с соседними датами, не со временем.
  const where = s.scope === 'наши даты' ? 'дату окна' : 'дату в архиве';
  return `\n📊 ${pct} % от цены на типичную ${where} ` +
         `(медиана по датам ${rub(s.median)}, самая дешёвая ${rub(s.min)}, дат: ${s.count})`;
};

const out = [];
const push = text => out.push({ json: { chat_id: CHAT_ID, text } });
const label = agg.route.label;

// ---------- сквозной билет ----------
const t = agg.through.best;
if (t) {
  const last = (store.through == null) ? null : Number(store.through);
  const was = (last == null) ? '' : ` (было ${rub(last)})`;

  let head = null;
  if (t.price <= THRESHOLD && (last == null || t.price < last)) head = `🔥 ${label}`;
  else if (last != null && t.price <= last * (1 - DROP_PCT / 100)) head = `📉 ${label}: цена упала`;
  store.through = t.price;

  if (head) {
    let text = `${head}\n${describe(t)}${was}` +
               verdict(`${agg.route.from}-${agg.route.to}`, t.price);
    if (head.startsWith('🔥')) text += '\nБери, пока не разобрали!';
    text += '\n⚠️ Цена из кэша Aviasales — проверь на сайте перевозчика.';
    push(text);
  }
}

// ---------- самостоятельная стыковка через Москву ----------
// Отдельный порог и отдельный счётчик: это две брони, риск на нас.
const s = agg.self.best;
if (s) {
  const last = (store.self == null) ? null : Number(store.self);
  const was = (last == null) ? '' : ` (было ${rub(last)})`;

  let head = null;
  if (s.price <= SELF_THRESHOLD && (last == null || s.price < last)) head = `🔥 ${label} через Москву`;
  else if (last != null && s.price <= last * (1 - DROP_PCT / 100)) head = `📉 ${label} через Москву: дешевле`;
  store.self = s.price;

  if (head) {
    push(`${head}\n${rub(s.price)} — две отдельные брони${was}\n` +
      `  1) ${describe(s.legA)}\n` +
      `  2) ${describe(s.legB)}\n` +
      `  стыковка ${s.layover_h} ч\n` +
      `⚠️ Билеты разные: опоздал на второй — никто ничего не должен. ` +
      `Багаж перерегистрировать, время стыковки проверить руками.` +
      // tutu отдаёт только цену на дату, без времени вылета — стыковка тут условная
      ((s.legA.src === 'tutu' || s.legB.src === 'tutu')
        ? `\n⚠️ Цена из календаря tutu: времени вылета там нет, стыковка посчитана грубо.`
        : ''));
  }
}

// ---------- hidden-city: только подсказка, без порога ----------
// Шлём не чаще раза в сутки и только если экономия заметная — иначе это спам.
const h = (agg.hidden.top || [])[0];
if (h && h.saving && h.saving >= 3000) {
  const day = new Date().toISOString().slice(0, 10);
  if (store.hiddenDay !== day) {
    store.hiddenDay = day;
    push(`🕵️ Подсказка hidden-city\n` +
      `${agg.route.from} → ${h.city} стоит ${rub(h.price)} — на ${rub(h.saving)} дешевле, ` +
      `чем до Актау (${dm(h.date)}, ${h.airline}, ${stops(h)}).\n` +
      `Проверь глазами: если этот рейс садится в Актау на стыковке — выходишь там.\n` +
      `⚠️ Только ручная кладь, только one-way, на пропускаемый сегмент не регистрироваться.`);
  }
}

return out; // 0..3 сообщения -> прямо в Telegram

// Запросы в Travelpayouts под первое плечо: Питер -> Актау, сентябрь 2026.
// Кроме сквозного маршрута тянем соседей, и вот зачем:
//   legA/legB — половинки московской схемы, из них в Aggregate собирается self-transfer;
//   deep      — города «за» Актау, нужны для подсказок hidden-city.
const MONTH = '2026-09';

const Q = [
  { origin: 'LED', destination: 'SCO', leg: 'through' },
  { origin: 'LED', destination: 'MOW', leg: 'legA' },   // MOW — метро-код: SVO+DME+VKO+ZIA
  { origin: 'MOW', destination: 'SCO', leg: 'legB' },
  { origin: 'LED', destination: 'ALA', leg: 'deep' },
  { origin: 'LED', destination: 'NQZ', leg: 'deep' },
  { origin: 'LED', destination: 'TAS', leg: 'deep' },
  { origin: 'LED', destination: 'GUW', leg: 'deep' },
];

return Q.map(q => ({ json: { ...q, month: MONTH } }));

// Исторические цены Travelpayouts — нужны, чтобы ответить на вопрос
// «а 28 000 ₽ это вообще дёшево?». Своей таблицы не заводим, берём чужой архив.
// Эндпоинт один — /v2/prices/latest: реально найденные цены за период
// (show_to_affiliates=false), по ним считаем медиану и исторический минимум.
// /v1/prices/calendar пробовали 2026-08-17 и ВЫКИНУЛИ: он отдаёт цены ТУДА-ОБРАТНО
// (все записи с return_at, 45–64 тыс. против one-way 12–22 тыс.) и игнорирует
// запрошенный месяц, растягиваясь на год вперёд. В медиане это давало +60 % к «обычной цене».
// URL и query собираются здесь, HTTP-нода их только исполняет.
const YEAR_START = '2026-01-01';
const ROUTES = [['LED', 'SCO'], ['LED', 'MOW'], ['MOW', 'SCO']];

const out = [];
for (const [origin, destination] of ROUTES) {
  out.push({ json: {
    key: `${origin}-${destination}`, kind: 'latest',
    url: 'https://api.travelpayouts.com/v2/prices/latest',
    qs: {
      origin, destination, currency: 'rub',
      period_type: 'year', beginning_of_period: YEAR_START,
      group_by: 'dates', one_way: 'true', sorting: 'price',
      page: '1', limit: '1000', show_to_affiliates: 'false',
    },
  } });
}
return out;

// ===== Плечо 1: Питер -> Актау (SCO), 15-25 сентября 2026 =====
// На старте живой источник один — Travelpayouts (кэш Aviasales, данные до 48 ч).
// Ноды перевозчиков (SCAT, Air Astana, FlyArystan, Уральские) добавляются позже,
// поэтому разбор идёт через общий плоский список offers[]: новому источнику
// достаточно положить туда свои записи в том же формате и он поедет дальше сам.
//
// offer = { from, to, date, depart_at, price, airline, transfers, src, kind }
//   kind: 'direct' | 'connect' | 'self' | 'hidden'
//   'self' (две отдельные брони) и 'hidden' считаются отдельно и в основной
//   порог алерта НЕ попадают — у них своя цена риска.
const SUF = ' Cmd'; // '' для крона, ' Cmd' для ветки команды

const WINDOW = { min: '2026-09-15', max: '2026-09-25' };
const HOME = 'LED';
const TARGET = 'SCO';
const HUB = 'MOW';                        // self-transfer через Москву
const DEEP = ['ALA', 'NQZ', 'TAS', 'GUW']; // города «за» Актау — под hidden-city
const ASSUMED_LEG_H = 3;                   // если перевозчик не отдал длительность
const MIN_LAYOVER_H = 4;                   // меньше — на самостоятельную стыковку не идём
const MAX_LAYOVER_H = 36;

const AIRLINES = {
  DP: 'Победа', '5N': 'Смартавиа', U6: 'Уральские', FV: 'Россия', SU: 'Аэрофлот',
  S7: 'S7', N4: 'Nordwind', WZ: 'Red Wings', A4: 'Азимут', YC: 'Ямал', UT: 'ЮТэйр',
  DV: 'SCAT', KC: 'Air Astana', IQ: 'Qazaq Air', HY: 'Uzbekistan', TK: 'Turkish',
  FZ: 'flydubai', J2: 'AZAL', VJ: 'VietJet', EK: 'Emirates', ZF: 'Азур', EO: 'Икар',
  // добавлены по факту выдачи 17.08.2026; C6 не расшифрован — покажется кодом как есть
  PC: 'Pegasus', B2: 'Belavia', '6R': 'Алроса',
};
const CITY = {
  LED: 'Санкт-Петербург', MOW: 'Москва', SCO: 'Актау', ALA: 'Алматы',
  NQZ: 'Астана', TAS: 'Ташкент', GUW: 'Атырау',
};

const inWindow = d => Boolean(d && d >= WINDOW.min && d <= WINDOW.max);
const hours = ms => ms / 3600000;

// --- 1. Travelpayouts v3: единственный источник на старте -------------------
const offers = [];
try {
  for (const item of $('Travelpayouts' + SUF).all()) {
    const r = item.json || {};
    if (r.success === false) continue;
    const rows = Array.isArray(r.data) ? r.data : (Array.isArray(r) ? r : []);

    for (const t of rows) {
      const depart_at = String(t.departure_at || t.depart_date || '');
      const date = depart_at.slice(0, 10);
      if (!inWindow(date)) continue;

      const price = Number(t.price != null ? t.price : t.value);
      if (!Number.isFinite(price) || price <= 0) continue;

      const transfers = Number(t.transfers != null ? t.transfers : t.number_of_changes);
      const dur = Number(t.duration_to || t.duration);

      offers.push({
        from: t.origin, to: t.destination, date, depart_at,
        price,
        airline: AIRLINES[t.airline] || t.airline || 'н/д',
        transfers: Number.isFinite(transfers) ? transfers : null,
        duration_min: Number.isFinite(dur) && dur > 0 ? dur : null,
        src: 'tp',
        kind: transfers === 0 ? 'direct' : 'connect',
        link: t.link || null,
      });
    }
  }
} catch (e) {}

// --- 1b. tutu: минимум по всем перевозчикам, включая тех, кого нет в кэше TP ---
// Ответ — плоский объект по датам, направление в нём НЕ указано, поэтому
// сопоставляем с запросами по индексу. Упавший запрос (continueRegularOutput)
// приходит item'ом с json.error — такую пару просто пропускаем.
const ruToIso = s => {
  const m = String(s || '').match(/^(\d{2})\.(\d{2})\.(\d{4})$/);
  return m ? `${m[3]}-${m[2]}-${m[1]}` : null;
};
try {
  const asked = $('Tutu Queries' + SUF).all();
  const answers = $('Tutu' + SUF).all();
  if (answers.length === asked.length) {
    asked.forEach((q, i) => {
      const data = (answers[i] || {}).json || {};
      if (data.error || Array.isArray(data)) return;
      for (const [dru, v] of Object.entries(data)) {
        const date = ruToIso(dru);
        if (!inWindow(date)) continue;
        const price = Number(v && v.price);
        if (!Number.isFinite(price) || price <= 0) continue;
        offers.push({
          from: q.json.from, to: q.json.to, date,
          // времени вылета tutu не даёт — для стыковки берём условный полдень,
          // поэтому self-transfer на tutu-ценах помечен как приблизительный
          depart_at: `${date}T12:00:00+03:00`,
          price, airline: 'мин. цена tutu', transfers: null, duration_min: null,
          src: 'tutu', kind: 'connect', link: null,
        });
      }
    });
  }
} catch (e) {}

// --- 2. Self-transfer через Москву -----------------------------------------
// Две отдельные брони: дешёвый лоукостер до Москвы + отдельный билет до Актау.
// Стыковку проверяем по времени вылета/прилёта, а не «по датам» — иначе бот
// предложит схему, где второй рейс улетает раньше, чем прилетает первый.
const legMin = (from, to) => {
  const byDate = {};
  for (const o of offers) {
    if (o.from !== from || o.to !== to) continue;
    if (!byDate[o.date] || o.price < byDate[o.date].price) byDate[o.date] = o;
  }
  return Object.values(byDate);
};

const arrivalOf = o => {
  const dep = new Date(o.depart_at);
  if (isNaN(dep)) return null;
  const mins = o.duration_min != null ? o.duration_min : ASSUMED_LEG_H * 60;
  return new Date(dep.getTime() + mins * 60000);
};

const selfCombos = [];
const legA = legMin(HOME, HUB);
const legB = legMin(HUB, TARGET);
for (const a of legA) {
  const arr = arrivalOf(a);
  for (const b of legB) {
    const dep = new Date(b.depart_at);
    if (!arr || isNaN(dep)) continue;
    const gap = hours(dep - arr);
    if (gap < MIN_LAYOVER_H || gap > MAX_LAYOVER_H) continue;
    selfCombos.push({
      price: a.price + b.price,
      date: a.date, arrive_date: b.date,
      layover_h: Math.round(gap * 10) / 10,
      legA: a, legB: b,
      kind: 'self', src: 'tp',
      from: HOME, to: TARGET,
      airline: `${a.airline} + ${b.airline}`,
    });
  }
}
selfCombos.sort((x, y) => x.price - y.price);

// --- 3. Hidden-city: пока только подсказка ---------------------------------
// Настоящий hidden-city требует сегментов маршрута, а Travelpayouts их не отдаёт.
// Поэтому честно сравниваем: если долететь «дальше» дешевле, чем до Актау —
// сообщаем цифру и просим проверить глазами, есть ли там стыковка в SCO.
const cheapest = list => list.slice().sort((a, b) => a.price - b.price)[0] || null;
const through = offers.filter(o => o.from === HOME && o.to === TARGET);
const bestThrough = cheapest(through);

const hidden = [];
for (const dst of DEEP) {
  const best = cheapest(offers.filter(o => o.from === HOME && o.to === dst));
  if (!best) continue;
  if (bestThrough && best.price >= bestThrough.price) continue; // не дешевле — не подсказка
  hidden.push({
    ...best, kind: 'hidden',
    saving: bestThrough ? bestThrough.price - best.price : null,
    city: CITY[dst] || dst,
  });
}
hidden.sort((a, b) => a.price - b.price);

// --- 4. Архив цен: медиана и исторический минимум ---------------------------
// Ответ на «дёшево или нет». Схемы этих эндпоинтов живьём не проверены,
// поэтому читаем максимально терпимо и молча пропускаем всё, что не разобралось.
// Копим два пула: цены на даты НАШЕГО окна (точнее) и вообще все (шире выборка).
// Если по окну набралось мало точек — падаем на общий пул, иначе медиана скачет.
const history = {}, historyWin = {};
const pushHist = (key, price, date) => {
  if (!Number.isFinite(price) || price <= 0) return;
  (history[key] = history[key] || []).push(price);
  if (inWindow(date)) (historyWin[key] = historyWin[key] || []).push(price);
};
try {
  for (const item of $('TP History' + SUF).all()) {
    const r = item.json || {};
    if (r.success === false) continue;
    const data = r.data;

    if (!Array.isArray(data)) continue;               // ждём массив от /v2/prices/latest
    for (const t of data) {
      if (!t || !t.origin || !t.destination) continue;
      if (t.return_date) continue;                     // цены туда-обратно нам не с чем сравнивать
      pushHist(`${t.origin}-${t.destination}`,
               Number(t.value != null ? t.value : t.price),
               String(t.depart_date || '').slice(0, 10));
    }
  }
} catch (e) {}

const MIN_SAMPLE = 10;
const stats = {};
for (const key of Object.keys(history)) {
  const win = historyWin[key] || [];
  const useWin = win.length >= MIN_SAMPLE;
  const s = (useWin ? win : history[key]).slice().sort((a, b) => a - b);
  stats[key] = {
    min: s[0],
    median: s[Math.floor(s.length / 2)],
    count: s.length,
    scope: useWin ? 'наши даты' : 'все даты',
  };
}

// --- 5. Сводка --------------------------------------------------------------
const byDate = {};
for (const o of through) {
  if (!byDate[o.date] || o.price < byDate[o.date].price) byDate[o.date] = o;
}

return [{ json: {
  window: WINDOW,
  route: { from: HOME, to: TARGET, label: `${CITY[HOME]} → ${CITY[TARGET]}` },
  through: {
    best: bestThrough,
    byDate: Object.values(byDate).sort((a, b) => (a.date < b.date ? -1 : 1)),
    count: through.length,
  },
  self: { best: selfCombos[0] || null, top: selfCombos.slice(0, 3), count: selfCombos.length },
  hidden: { top: hidden.slice(0, 3), count: hidden.length },
  stats,
  count: offers.length,
  bySource: offers.reduce((acc, o) => { acc[o.src] = (acc[o.src] || 0) + 1; return acc; }, {}),
} }];

// Ответ на /prices по первому плечу: Питер -> Актау.
const a = $('Aggregate Cmd').first().json;
const chat_id = $('On Command').first().json.message.chat.id;

const MONTHS = ['янв', 'фев', 'мар', 'апр', 'мая', 'июн',
                'июл', 'авг', 'сен', 'окт', 'ноя', 'дек'];
const dm = iso => {
  const p = String(iso).split('-');
  return p.length === 3 ? `${Number(p[2])} ${MONTHS[Number(p[1]) - 1]}` : iso;
};
const rub = n => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + ' ₽';
const stops = o => o.transfers === 0 ? 'прямой'
  : o.transfers > 0 ? `${o.transfers} пересадк${o.transfers === 1 ? 'а' : 'и'}`
  : '';
const describe = o => `${rub(o.price)} · ${dm(o.date)} · ${o.airline}` +
  (stops(o) ? ` · ${stops(o)}` : '');

let text = `✈️ ${a.route.label}, ${dm(a.window.min)} – ${dm(a.window.max)}\n\n`;

if (a.through.best) {
  text += `Одним билетом: ${describe(a.through.best)}\n`;
  const s = (a.stats || {})[`${a.route.from}-${a.route.to}`];
  if (s && s.median) {
    text += `  ${Math.round((a.through.best.price / s.median) * 100)} % от цены на типичную дату ` +
            `(медиана по датам ${rub(s.median)}, самая дешёвая ${rub(s.min)}, дат: ${s.count})\n`;
  }
} else {
  text += `Одним билетом: ничего не нашлось\n`;
}

if (a.self.best) {
  text += `\nЧерез Москву двумя билетами: ${rub(a.self.best.price)}\n`;
  for (const c of a.self.top) {
    text += `  • ${rub(c.price)}: ${describe(c.legA)} + ${describe(c.legB)}, стыковка ${c.layover_h} ч\n`;
  }
  text += `  ⚠️ Две отдельные брони, стыковка на твой риск.\n`;
}

if ((a.hidden.top || []).length) {
  text += `\n🕵️ Дальше Актау стоит дешевле (проверить на стыковку в SCO):\n`;
  for (const h of a.hidden.top) {
    text += `  • ${a.route.from} → ${h.city}: ${rub(h.price)} (${dm(h.date)}, ${h.airline})` +
            (h.saving ? ` — минус ${rub(h.saving)}\n` : '\n');
  }
}

if ((a.through.byDate || []).length) {
  text += `\nПо датам (одним билетом):\n`;
  for (const o of a.through.byDate) text += `  ${dm(o.date)} — ${rub(o.price)}\n`;
}

text += `\nВсего вариантов: ${a.count} (${Object.entries(a.bySource || {})
  .map(([k, v]) => `${k}: ${v}`).join(', ')}).\n` +
  `«мин. цена tutu» — минимум по всем перевозчикам без указания рейса, ` +
  `остальное — кэш Aviasales до 48 ч. Перед покупкой проверь на сайте перевозчика.`;

return [{ json: { chat_id, text } }];

// Уведомление о падении воркфлоу. Троттлинг на ноду — 30 мин:
// без него лежащий внешний API заваливает чат десятками одинаковых сообщений.
const QUIET_MS = 30 * 60 * 1000;
const e = $json.execution || {};
const err = e.error || {};
const wf = $json.workflow || {};
const node = e.lastNodeExecuted || '?';
const s = $getWorkflowStaticData('global');
if (!s.errAlerts) s.errAlerts = {};
const st = s.errAlerts[node] || { last: 0, suppressed: 0 };
const now = Date.now();
if (now - st.last < QUIET_MS) { st.suppressed += 1; s.errAlerts[node] = st; return []; }
const repeats = st.suppressed;
s.errAlerts[node] = { last: now, suppressed: 0 };
const text =
  `⚠️ FlightWatch SCO упал\nВоркфлоу: ${wf.name || '?'}\nНода: ${node}\n` +
  `Ошибка: ${err.message || 'без текста'}` +
  (repeats ? `\n(за последние 30 мин ещё ${repeats} таких, они скрыты)` : '') +
  (e.url ? `\n${e.url}` : '');
return [{ json: { chat_id: '648226895', text } }];

// tutu.ru — открытый календарь минимальных цен, без токена и капчи.
// Ценен тем, что показывает минимум по ВСЕМ перевозчикам, включая тех, кого нет
// в кэше Aviasales. Перевозчика при этом не называет — только цену на дату.
// ВАЖНО: departure_geo_id — это внутренний id tutu, НЕ IATA.
// Достаётся из https://avia.tutu.ru/suggest/city/v5/?name=Город&direction=to (поле id).
// Проверено 2026-08-17: LED=75, MOW=491, Актау=112, Алматы=117, Астана=128, Ташкент=424.
const ROUTES = [
